const cosiItems = $input.all();
const hubspotItems = $('Combine Approval Results').all();

function normalizeDomain(domain) {
  return String(domain || '')
    .trim()
    .toLowerCase()
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .replace(/\/$/, '');
}

// Build HubSpot domain -> companyId map
const hubspotMap = new Map();

for (const item of hubspotItems) {
  const domain = normalizeDomain(item.json?.properties?.domain?.value);
  const companyId = item.json?.companyId;

  if (domain && companyId) {
    hubspotMap.set(domain, companyId);
  }
}

// Add matched HubSpot companyId to each Cosi item
return cosiItems.map(item => {
  const cosiDomain = normalizeDomain(item.json?.website_domain);
  const matchedCompanyId = hubspotMap.get(cosiDomain) ?? null;

  return {
    json: {
      ...item.json,
      hubspot_companyId: matchedCompanyId,
    },
  };
});
